package server

// Authorization policies for the root routes. See route_auth_policy_test.go
// for the classes; routePolicyFile says which file a new route belongs in.
func init() {
	declareRoutePolicies(map[string]routePolicy{
		"GET /api/github/api/v3/repos/{owner}/{repo}":                          handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/pulls":                    handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"POST /api/github/api/v3/repos/{owner}/{repo}/pulls":                   handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/pulls/{number}":           handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"PATCH /api/github/api/v3/repos/{owner}/{repo}/pulls/{number}":         handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/pulls/{number}/files":     handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/pulls/{number}/comments":  handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"PUT /api/github/api/v3/repos/{owner}/{repo}/pulls/{number}/merge":     handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/hooks":                    handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"POST /api/github/api/v3/repos/{owner}/{repo}/hooks":                   handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"PATCH /api/github/api/v3/repos/{owner}/{repo}/hooks/{hookID}":         handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/commits/{sha}/status":     handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /api/github/api/v3/repos/{owner}/{repo}/commits/{sha}/check-runs": handlerAuth("GitHub-compatible API: compatRequest authenticates the API key header and authorizes the repository"),
		"GET /.well-known/helix-domain-verify/{token}":                         public("custom-domain ownership proof; echoes only a token the domain owner already published"),
		"POST /v1/chat/completions":                                            handlerAuth("authMiddleware.auth wrapper; handler requires a user or runner, and authorizes an app_id in the body"),
		"POST /v1/responses":                                                   handlerAuth("authMiddleware.auth wrapper; handler requires a user"),
		"POST /v1/embeddings":                                                  handlerAuth("authMiddleware.auth wrapper; handler requires a user"),
		"GET /v1/models":                                                       handlerAuth("authMiddleware.auth wrapper; listModels requires a user or runner"),
		"POST /v1/messages":                                                    handlerAuth("authMiddleware.auth wrapper; handler requires a user"),
		"POST /openai/deployments/{model}/chat/completions":                    handlerAuth("authMiddleware.auth wrapper; handler requires a user or runner, and authorizes an app_id in the body"),
		"ANY <matcher>":                                          handlerAuth("/debug/*: pprof for global admins, 404 for everyone else (requireAdminOrNotFound)"),
		"GET /git/{repo_id}/info/refs":                           handlerAuth("git smart HTTP: GitHTTPServer.authMiddleware authenticates the API key and authorizes the repository"),
		"POST /git/{repo_id}/git-upload-pack":                    handlerAuth("git smart HTTP: GitHTTPServer.authMiddleware authenticates the API key and authorizes the repository"),
		"POST /git/{repo_id}/git-receive-pack":                   handlerAuth("git smart HTTP: GitHTTPServer.authMiddleware authenticates the API key and authorizes the repository"),
		"GET /git/{repo_id}/clone-info":                          handlerAuth("git smart HTTP: GitHTTPServer.authMiddleware authenticates the API key and authorizes the repository"),
		"GET /git/{repo_id}/status":                              handlerAuth("git smart HTTP: GitHTTPServer.authMiddleware authenticates the API key and authorizes the repository"),
		"GET /artifacts/{artifact_id}/embed":                     handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"HEAD /artifacts/{artifact_id}/embed":                    handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"GET /artifacts/{artifact_id}/embed/":                    handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"HEAD /artifacts/{artifact_id}/embed/":                   handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"GET /artifacts/{artifact_id}/embed/{artifact_path:.*}":  handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"HEAD /artifacts/{artifact_id}/embed/{artifact_path:.*}": handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"GET /artifacts/{artifact_id}/document":                  handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"HEAD /artifacts/{artifact_id}/document":                 handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"GET /artifacts/{artifact_id}/download":                  handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"HEAD /artifacts/{artifact_id}/download":                 handlerAuth("extractMiddleware; non-public artifacts need a caller authorized to the project").authz("authorizeUserToProjectByID"),
		"GET /connect/intake":                                    public("secret-intake page shell; the link token is redeemed by POST /connect/intake/redeem"),
		"GET /connect/intake/boot.js":                            public("secret-intake page script"),
		"GET /connect/intake/{intake_id:sci_[A-Za-z0-9_-]+}":     public("secret-intake page shell for one intake; holds no data"),
		"POST /connect/intake/redeem":                            public("the one-time intake link token is the credential"),
		"POST /connect/intake/submit":                            public("the redeemed intake form token is the credential"),
		"ANY /":                                                  public("SPA catch-all: frontend assets"),
	})
}
